WITH latest_match AS (SELECT s.id, s.email, s.segment, s.is_active, s.credit_limit, s.age, latest.account_type FROM customers s LEFT JOIN LATERAL (SELECT c.account_type FROM accounts c WHERE c.customer_id = s.id AND c.opened_date <= s.signup_date ORDER BY c.opened_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, email, segment, credit_limit, age, account_type FROM latest_match;
